import { stageColor, stageLabel, type BootStage } from '../../services/server-control.service.js';
import type { DotColor } from '../status-pill/status-dot/status-dot.component.js';

/**
 * Story 381 (pwa-shell-22): the colour rules the status pill shares with the status screen's
 * sections, as plain functions. The pill imported four section components — the Health Connect
 * sync panel among them — only to call their static helpers, which put the whole status screen
 * in the bundle home loads first.
 */

export function connectivityStatus(online: boolean): { color: DotColor; label: string | null } {
    return { color: online ? 'green' : 'red', label: online ? null : 'Offline' };
}

export function serverStatus(stage: BootStage): { color: DotColor; label: string } {
    return { color: stageColor(stage), label: stageLabel(stage) };
}

export function syncStatus(count: number, hasError: boolean): { color: DotColor; count: number } {
    return { color: hasError ? 'red' : count > 0 ? 'orange' : 'green', count };
}

export function hcBridgeStatus(reachable: boolean | null): { color: DotColor } {
    return { color: reachable ? 'green' : 'gray' };
}
